"""Look into sim/captured: insp.py urls <site> | view <site> <url-ending> [chars] | grep <site> <regex> | body <site> <url-ending> | count"""
import collections
import glob
import json
import re
import sys

ROOT = "/Users/akshatkhair/Documents/Projects/error404ai_ehl_finals/.claude/worktrees/sim-portals/sim/captured/"
cmd, args = sys.argv[1], sys.argv[2:]


def exchanges(site):
    return [json.loads(line) for line in open(ROOT + site + "/exchanges.jsonl", encoding="utf-8")]


def pages(site):
    return [json.load(open(p, encoding="utf-8")) for p in sorted(glob.glob(ROOT + site + "/pages/*.json"))]


if cmd == "count":
    for site in ("tender-portal", "customer-portal", "erp", "mail"):
        print(site, len(pages(site)), "pages", len(exchanges(site)), "responses")
elif cmd == "urls":
    seen = collections.OrderedDict()
    for e in exchanges(args[0]):
        key = (e["method"], e["url"].replace("{{origin}}", ""), (e["post"] or "")[:int(args[1]) if args[1:] else 0],
               e["status"], e["location"])
        seen[key] = seen.get(key, 0) + 1
    for (m, u, p, st, loc), c in seen.items():
        print(f"{m} {u[:140]} {p} {st} {loc or ''} x{c}")
elif cmd == "view":
    found = [r for r in pages(args[0]) if r["url"].replace("{{origin}}", "").endswith(args[1])]
    for r in found[-1:] if args[3:] != ["all"] else found:
        print("#####", r["n"], r["url"], "|", r["title"], "| note:", r["note"], "| events:", r["events"])
        print(r["view"][:int(args[2]) if args[2:] else 3000])
        for f in r["forms"]:
            print("  FORM", f["method"], f["action"].replace("{{origin}}", ""),
                  [(x["tag"], x["type"], x["name"], x.get("text"), x.get("value")) for x in f["fields"]])
    if not found:
        print("no page ends with", args[1])
elif cmd == "grep":
    rx = re.compile(args[1])
    for r in pages(args[0]):
        hits = sorted(set(m.group(0) for m in rx.finditer(r["view"])))
        if hits:
            print(r["n"], r["url"].replace("{{origin}}", "")[:80], hits[:12])
elif cmd == "body":
    found = [e for e in exchanges(args[0]) if e["url"].replace("{{origin}}", "").endswith(args[1]) and e["body"]]
    text = open(ROOT + args[0] + "/bodies/" + found[-1]["body"], encoding="utf-8").read()
    if "nostyle" in args:
        text = re.sub(r"<style>.*?</style>", "<style/>", text, flags=re.S)
    print(text[:int(args[2]) if args[2:] and args[2].isdigit() else 6000])

